import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { screen, render } from "@testing-library/react";
import { PopperContent } from "../PopperContent";
import { RDSThemeProvider } from "../../../rdsThemeProvider";
import { CallistoThemeMap } from "../../../callistoTheme";
describe("PopperContent", () => {
    const testIds = {
        header: "popper-content-header",
        metadata: "popper-content-metadata-slot",
        popperContent: "popper-content",
        status: "popper-content-status-slot",
        title: "popper-content-title",
    };
    it("should render popper content without header", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(PopperContent, { children: "popper-content" }) }));
        expect(screen.getByTestId(testIds.popperContent)).toHaveTextContent("popper-content");
        expect(screen.queryByTestId(testIds.header)).not.toBeInTheDocument();
    });
    it("should apply custom test id correctly", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(PopperContent, { "data-testid": "my-custom-test-id", children: "popper-content" }) }));
        expect(screen.getByTestId("my-custom-test-id")).toHaveTextContent("popper-content");
        expect(screen.queryByTestId(testIds.popperContent)).not.toBeInTheDocument();
    });
    it("should render header and title when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(PopperContent, { title: "Title", children: "popper-content" }) }));
        expect(screen.getByTestId(testIds.popperContent)).toHaveTextContent("popper-content");
        expect(screen.getByTestId(testIds.header)).toBeInTheDocument();
        expect(screen.getByTestId(testIds.title)).toHaveTextContent("Title");
        expect(screen.queryByRole("separator")).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.metadata)).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.status)).not.toBeInTheDocument();
    });
    it("should render header and status when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(PopperContent, { statusSlot: "Status", children: "popper-content" }) }));
        expect(screen.getByTestId(testIds.popperContent)).toHaveTextContent("popper-content");
        expect(screen.getByTestId(testIds.header)).toBeInTheDocument();
        expect(screen.getByTestId(testIds.status)).toHaveTextContent("Status");
        expect(screen.queryByRole("separator")).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.metadata)).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.title)).not.toBeInTheDocument();
    });
    it("should render header and metatdata when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(PopperContent, { metadataSlot: "Metadata", children: "popper-content" }) }));
        expect(screen.getByTestId(testIds.popperContent)).toHaveTextContent("popper-content");
        expect(screen.getByTestId(testIds.header)).toBeInTheDocument();
        expect(screen.getByTestId(testIds.metadata)).toHaveTextContent("Metadata");
        expect(screen.queryByRole("separator")).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.status)).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.title)).not.toBeInTheDocument();
    });
    it("should render header and divider when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(PopperContent, { divider: true, children: "popper-content" }) }));
        expect(screen.getByTestId(testIds.popperContent)).toHaveTextContent("popper-content");
        expect(screen.getByTestId(testIds.header)).toBeInTheDocument();
        expect(screen.queryByRole("separator")).toBeInTheDocument();
        expect(screen.queryByTestId(testIds.metadata)).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.status)).not.toBeInTheDocument();
        expect(screen.queryByTestId(testIds.title)).not.toBeInTheDocument();
    });
    it("should render all items when provided", () => {
        render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: "dark", children: _jsx(PopperContent, { divider: true, metadataSlot: "Metadata", statusSlot: "Status", title: "Title", children: "popper-content" }) }));
        expect(screen.getByTestId(testIds.popperContent)).toHaveTextContent("popper-content");
        expect(screen.getByTestId(testIds.header)).toBeInTheDocument();
        expect(screen.getByRole("separator")).toBeInTheDocument();
        expect(screen.getByTestId(testIds.metadata)).toHaveTextContent("Metadata");
        expect(screen.getByTestId(testIds.status)).toHaveTextContent("Status");
        expect(screen.getByTestId(testIds.title)).toHaveTextContent("Title");
    });
});
